changeSet.sql:
INSERT INTO m_permission(grouping,code,entity_name,action_name,can_maker_checker)
SELECT 'report',r.report_name,r.entity_name,'READ',false FROM (
  SELECT 'READ_KYCNaturalPerson' report_name,'KYCNaturalPerson' entity_name
  UNION ALL SELECT 'READ_KYCLegalPerson','KYCLegalPerson'
) r WHERE NOT EXISTS(SELECT 1 FROM m_permission p WHERE p.code=r.report_name);
